ime` Int16, `Div1WheelsOff` Int16, `Div1TailNum` LowCardinality(String), `Div2Airport` LowCardinality(String), `Div2AirportID` Int32, `Div2AirportSeqID` Int32, `Div2WheelsOn` Int16, `Div2TotalGTime` Int16, `Div2LongestGTime` Int16, `Div2WheelsOff` Int16, `Div2TailNum` LowCardinality(String), `Div3Airport` LowCardinality(String), `Div3AirportID` Int32, `Div3AirportSeqID` Int32, `Div3WheelsOn` Int16, `Div3TotalGTime` Int16, `Div3LongestGTime` Int16, `Div3WheelsOff` Int16, `Div3TailNum` LowCardinality(String), `Div4Airport` LowCardinality(String), `Div4AirportID` Int32, `Div4AirportSeqID` Int32, `Div4WheelsOn` Int16, `Div4TotalGTime` Int16, `Div4LongestGTime` Int16, `Div4WheelsOff` Int16, `Div4TailNum` LowCardinality(String), `Div5Airport` LowCardinality(String), `Div5AirportID` Int32, `Div5AirportSeqID` Int32, `Div5WheelsOn` Int16, `Div5TotalGTime` Int16, `Div5LongestGTime` Int16, `Div5WheelsOff` Int16, `Div5TailNum` LowCardinality(String)) ENGINE = MergeTree ORDER BY (Year, Quarter, Month, DayofMonth, FlightDate, IATA_CODE_Reporting_Airline) SETTINGS index_granularity = 8192;

