CREATE TABLE default.query_metric_runs_v1 (`event_date` Date, `check_start_time` DateTime, `pr_number` Int32, `old_sha` String, `new_sha` String, `arch` LowCardinality(String), `baseline_kind` LowCardinality(String), `workflow_name` LowCardinality(String), `base_branch` LowCardinality(String), `report_url` String, `instance_type` LowCardinality(String), `instance_id` String, `test` LowCardinality(String), `query_index` Int32, `query_display_name` String, `side` LowCardinality(String), `query_id` String, `metric_name` LowCardinality(String), `metric_value` Float64) ENGINE = MergeTree PARTITION BY toYYYYMM(event_date) ORDER BY (test, query_index, metric_name, arch, event_date, side) SETTINGS index_granularity = 8192;

CREATE TABLE default.query_metrics_v2 (`event_date` Date, `event_time` DateTime, `pr_number` UInt32, `old_sha` String, `new_sha` String, `test` LowCardinality(String), `query_index` UInt32, `query_display_name` String, `metric` LowCardinality(String), `old_value` Float32, `new_value` Float32, `diff` Float32, `stat_threshold` Float32, `arch` String DEFAULT '', `workflow_name` String DEFAULT '', `base_branch` String DEFAULT '', `report_url` String DEFAULT '', `instance_type` String DEFAULT '', `instance_id` String DEFAULT '') ENGINE = MergeTree PARTITION BY toYYYYMM(event_date) ORDER BY (new_sha, test, query_index, metric) SETTINGS index_granularity = 8192;

CREATE TABLE default.rdns (`timestamp` DateTime, `address` IPv4, `domain` String) ENGINE = MergeTree ORDER BY address SETTINGS index_granularity = 8192;

CREATE TABLE default.recipes (`title` String, `ingredients` Array(String), `directions` Array(String), `link` String, `source` LowCardinality(String), `NER` Array(String)) ENGINE = MergeTree ORDER BY title SETTINGS index_granularity = 8192;

CREATE TABLE default.repos (`full_name` String, `owner_type` LowCardinality(String), `description` String, `fork` Bool, `created_at` DateTime, `updated_at` DateTime, `pushed_at` DateTime, `homepage` String, `size` UInt64, `stargazers_count` UInt32, `forks_count` UInt32, `subscribers_count` UInt32, `language` LowCardinality(String), `has_issues` Bool, `has_projects` Bool, `has_downloads` Bool, `has_wiki` Bool, `has_pages` Bool, `archived` Bool, `disabled` Bool, `is_template` Bool, `allow_forking` Bool, `open_issues_count` UInt32, `license_key` LowCardinality(String), `topics` Array(LowCardinality(String)), `default_branch` LowCardinality(String)) ENGINE = MergeTree ORDER BY full_name SETTINGS index_granularity = 8192;

CREATE TABLE default.repos_history (`time` DateTime DEFAULT now(), `id` UInt64, `name` String, `owner` Tuple(login String, id UInt64, type LowCardinality(String), site_admin Bool), `full_name` String, `description` String, `fork` Bool, `created_at` DateTime, `updated_at` DateTime, `pushed_at` DateTime, `homepage` String, `size` UInt64, `stargazers_count` UInt32, `language` LowCardinality(String), `has_issues` Bool, `has_projects` Bool, `has_downloads` Bool, `has_wiki` Bool, `has_pages` Bool, `has_discussions` Bool, `forks_count` UInt32, `mirror_url` String, `archived` Bool, `disabled` Bool, `open_issues_count` UInt32, `license` Tuple(key LowCardinality(String), name LowCardinality(String), spdx_id LowCardinality(String)), `allow_forking` Bool, `is_template` Bool, `web_commit_signoff_required` Bool, `topics` Array(LowCardinality(String)), `visibility` LowCardinality(String), `default_branch` LowCardinality(String), `network_count` UInt32, `subscribers_count` UInt32) ENGINE = MergeTree ORDER BY (full_name, time) SETTINGS index_granularity = 8192;

CREATE TABLE default.repos_raw (`data` String) ENGINE = MergeTree ORDER BY tuple() SETTINGS index_granularity = 8192;

CREATE TABLE default.run_attributes_v1 (`old_sha` String, `new_sha` String, `metric` LowCardinality(String), `metric_value` String) ENGINE = MergeTree ORDER BY (old_sha, new_sha) SETTINGS index_granularity = 8192;

CREATE TABLE default.stock (`symbol` String, `date` Date, `price` Decimal(9, 3), `volume` UInt32, `open` Decimal(9, 3), `low` Decimal(9, 3), `high` Decimal(9, 3)) ENGINE = MergeTree ORDER BY (symbol, date) SETTINGS index_granularity = 8192;

CREATE TABLE default.tranco (`date` Date, `rank` UInt32, `domain` LowCardinality(String)) ENGINE = MergeTree ORDER BY (domain, date) SETTINGS index_granularity = 8192;

CREATE TABLE default.trips (`trip_id` UInt32, `vendor_id` Enum8('1' = 1, '2' = 2, '3' = 3, '4' = 4, 'CMT' = 5, 'VTS' = 6, 'DDS' = 7, 'B02512' = 10, 'B02598' = 11, 'B02617' = 12, 'B02682' = 13, 'B02764' = 14, '' = 15), `pickup_date` Date, `pickup_datetime` DateTime, `dropoff_date` Date, `dropoff_datetime` DateTime, `store_and_fwd_flag` UInt8, `rate_code_id` UInt8, `pickup_longitude` Float64, `pickup_latitude` Float64, `dropoff_longitude` Float64, `dropoff_latitude` Float64, `passenger_count` UInt8, `trip_distance` Float64, `fare_amount` Float32, `extra` Float32, `mta_tax` Float32, `tip_amount` Float32, `tolls_amount` Float32, `ehail_fee` Float32, `improvement_surcharge` Float32, `total_amount` Float32, `payment_type_` Enum8('UNK' = 0, 'CSH' = 1, 'CRE' = 2, 'NOC' = 3, 'DIS' = 4), `trip_type` UInt8, `pickup` FixedString(25), `dropoff` FixedString(25), `cab_type` Enum8('yellow' = 1, 'green' = 2, 'uber' = 3), `pickup_nyct2010_gid` Int8, `pickup_ctlabel` Float32, `pickup_borocode` Int8, `pickup_ct2010` String, `pickup_boroct2010` FixedString(7), `pickup_cdeligibil` String, `pickup_ntacode` FixedString(4), `pickup_ntaname` String, `pickup_puma` UInt16, `dropoff_nyct2010_gid` UInt8, `dropoff_ctlabel` Float32, `dropoff_borocode` UInt8, `dropoff_ct2010` String, `dropoff_boroct2010` FixedString(7), `dropoff_cdeligibil` String, `dropoff_ntacode` FixedString(4), `dropoff_ntaname` String, `dropoff_puma` UInt16) ENGINE = MergeTree PARTITION BY toYYYYMM(pickup_date) ORDER BY pickup_datetime SETTINGS index_granularity = 8192;

CREATE TABLE default.uk_price_paid (`price` UInt32, `date` Date, `postcode1` LowCardinality(String), `postcode2` LowCardinality(String), `type` Enum8('other' = 0, 'terraced' = 1, 'semi-detached' = 2, 'detached' = 3, 'flat' = 4), `is_new` UInt8, `duration` Enum8('unknown' = 0, 'freehold' = 1, 'leasehold' = 2), `addr1` String, `addr2` String, `street` LowCardinality(String), `locality` LowCardinality(String), `town` LowCardinality(String), `district` LowCardinality(String), `county` LowCardinality(String)) ENGINE = MergeTree ORDER BY (postcode1, postcode2, addr1, addr2) SETTINGS index_granularity = 8192;

CREATE TABLE default.version_history (`check_start_time` DateTime, `pull_request_number` UInt32, `pull_request_url` LowCardinality(String), `commit_sha` LowCardinality(String), `parent_commits_sha` Array(String), `commit_url` LowCardinality(String), `version` LowCardinality(String), `docker_tag` LowCardinality(String), `git_ref` LowCardinality(String)) ENGINE = MergeTree ORDER BY check_start_time SETTINGS index_granularity = 8192;

CREATE TABLE default.workflow_jobs (`id` UInt64, `run_id` UInt64, `workflow_name` LowCardinality(String), `head_branch` LowCardinality(String), `run_url` String, `run_attempt` UInt16, `node_id` String, `head_sha` String, `url` String, `html_url` String, `status` Enum8('waiting' = 1, 'queued' = 2, 'in_progress' = 3, 'completed' = 4), `conclusion` LowCardinality(String), `started_at` DateTime, `completed_at` DateTime, `name` LowCardinality(String), `steps` UInt16, `check_run_url` String, `labels` Array(LowCardinality(String)), `runner_id` UInt64, `runner_name` String, `runner_group_id` UInt64, `runner_group_name` LowCardinality(String), `repository` LowCardinality(String), `updated_at` DateTime DEFAULT now()) ENGINE = MergeTree PARTITION BY toStartOfMonth(started_at) ORDER BY (id, updated_at) SETTINGS index_granularity = 8192;

CREATE TABLE git_clickhouse.commits (`hash` String, `author` LowCardinality(String), `time` DateTime, `message` String, `files_added` UInt32, `files_deleted` UInt32, `files_renamed` UInt32, `files_modified` UInt32, `lines_added` UInt32, `lines_deleted` UInt32, `hunks_added` UInt32, `hunks_removed` UInt32, `hunks_changed` UInt32) ENGINE = MergeTree ORDER BY time SETTINGS index_granularity = 8192;

CREATE TABLE git_clickhouse.file_changes (`change_type` Enum8('Add' = 1, 'Delete' = 2, 'Modify' = 3, 'Rename' = 4, 'Copy' = 5, 'Type' = 6), `path` LowCardinality(String), `old_path` LowCardinality(String), `file_extension` LowCardinality(String), `lines_added` UInt32, `lines_deleted` UInt32, `hunks_added` UInt32, `hunks_removed` UInt32, `hunks_changed` UInt32, `commit_hash` String, `author` LowCardinality(String), `time` DateTime, `commit_message` String, `commit_files_added` UInt32, `commit_files_deleted` UInt32, `commit_files_renamed` UInt32, `commit_files_modified` UInt32, `commit_lines_added` UInt32, `commit_lines_deleted` UInt32, `commit_hunks_added` UInt32, `commit_hunks_removed` UInt32, `commit_hunks_changed` UInt32) ENGINE = MergeTree ORDER BY time SETTINGS index_granularity = 8192;

CREATE TABLE git_clickhouse.line_changes (`sign` Int8, `line_number_old` UInt32, `line_number_new` UInt32, `hunk_num` UInt32, `hunk_start_line_number_old` UInt32, `hunk_start_line_number_new` UInt32, `hunk_lines_added` UInt32, `hunk_lines_deleted` UInt32, `hunk_context` LowCardinality(String), `line` LowCardinality(String), `indent` UInt8, `line_type` Enum8('Empty' = 0, 'Comment' = 1, 'Punct' = 2, 'Code' = 3), `prev_commit_hash` String, `prev_author` LowCardinality(String), `prev_time` DateTime, `file_change_type` Enum8('Add' = 1, 'Delete' = 2, 'Modify' = 3, 'Rename' = 4, 'Copy' = 5, 'Type' = 6), `path` LowCardinality(String), `old_path` LowCardinality(String), `file_extension` LowCardinality(String), `file_lines_added` UInt32, `file_lines_deleted` UInt32, `file_hunks_added` UInt32, `file_hunks_removed` UInt32, `file_hunks_changed` UInt32, `commit_hash` String, `author` LowCardinality(String), `time` DateTime, `commit_message` String, `commit_files_added` UInt32, `commit_files_deleted` UInt32, `commit_files_renamed` UInt32, `commit_files_modified` UInt32, `commit_lines_added` UInt32, `commit_lines_deleted` UInt32, `commit_hunks_added` UInt32, `commit_hunks_removed` UInt32, `commit_hunks_changed` UInt32) ENGINE = MergeTree ORDER BY time SETTINGS index_granularity = 8192;

CREATE TABLE mgbench.logs1 (`log_time` DateTime, `machine_name` LowCardinality(String), `machine_group` LowCardinality(String), `cpu_idle` Nullable(Float32), `cpu_nice` Nullable(Float32), `cpu_system` Nullable(Float32), `cpu_user` Nullable(Float32), `cpu_wio` Nullable(Float32), `disk_free` Nullable(Float32), `disk_total` Nullable(Float32), `part_max_used` Nullable(Float32), `load_fifteen` Nullable(Float32), `load_five` Nullable(Float32), `load_one` Nullable(Float32), `mem_buffers` Nullable(Float32), `mem_cached` Nullable(Float32), `mem_free` Nullable(Float32), `mem_shared` Nullable(Float32), `swap_free` Nullable(Float32), `bytes_in` Nullable(Float32), `bytes_out` Nullable(Float32)) ENGINE = MergeTree ORDER BY (machine_group, machine_name, log_time) SETTINGS index_granularity = 8192;

CREATE TABLE mgbench.logs2 (`log_time` DateTime, `client_ip` IPv4, `request` String, `status_code` UInt16, `object_size` UInt64) ENGINE = MergeTree ORDER BY log_time SETTINGS index_granularity = 8192;

CREATE TABLE mgbench.logs3 (`log_time` DateTime64(3), `device_id` FixedString(15), `device_name` LowCardinality(String), `device_type` LowCardinality(String), `device_floor` UInt8, `event_type` LowCardinality(String), `event_unit` FixedString(1), `event_value` Nullable(Float32)) ENGINE = MergeTree ORDER BY (event_type, log_time) SETTINGS index_granularity = 8192;

