-- ── Views ──────────────────────────────────────────────────────────────────
-- Last on purpose. A materialized view created before the inserts would fire
-- as its source filled and write rows into a target that already holds its
-- own extract, so the fixture would load differently every time.

CREATE MATERIALIZED VIEW default.hackernews_changes_to_history TO default.hackernews_history (`update_time` DateTime, `id` UInt32, `deleted` UInt8, `type` Enum8('story' = 1, 'comment' = 2, 'poll' = 3, 'pollopt' = 4, 'job' = 5), `by` LowCardinality(String), `time` DateTime, `text` String, `dead` UInt8, `parent` UInt32, `poll` UInt32, `kids` Array(UInt32), `url` String, `score` Int32, `title` String, `parts` Array(UInt32), `descendants` Int32) AS SELECT * FROM default.hackernews_changes_items;

CREATE VIEW default.perf_change_points_live (`test` String, `query_index` UInt32, `query_display_name` String, `metric` String, `sha` String, `leading_sha` String, `next_leading_sha` String, `event_time` DateTime, `leading_time` DateTime, `magnitude` Float64, `magnitude_lo` Float64, `magnitude_hi` Float64, `is_multiplicative` UInt8, `direction` String, `disparity` Float64, `disparity_lo` Float64, `disparity_hi` Float64, `window_size` UInt32, `causal_sha` String, `causal_time` DateTime, `causal_range_start` String, `causal_range_end` String, `detector` String, `version` DateTime, `is_deleted` UInt8) AS SELECT * FROM default.perf_change_points FINAL WHERE is_deleted = 0;

CREATE VIEW default.perf_change_points_live_v2 (`arch` String, `test` String, `query_index` UInt32, `query_display_name` String, `metric` String, `sha` String, `leading_sha` String, `next_leading_sha` String, `event_time` DateTime, `leading_time` DateTime, `magnitude` Float64, `magnitude_lo` Float64, `magnitude_hi` Float64, `is_multiplicative` UInt8, `direction` String, `disparity` Float64, `disparity_lo` Float64, `disparity_hi` Float64, `window_size` UInt32, `causal_sha` String, `causal_time` DateTime, `causal_range_start` String, `causal_range_end` String, `detector` String, `version` DateTime, `is_deleted` UInt8) AS SELECT * FROM default.perf_change_points_v2 FINAL WHERE is_deleted = 0;

CREATE VIEW default.perf_change_points_trust_rollup (`test` String, `query_index` UInt32, `metric` String, `leading_sha` String, `cp_time` DateTime, `magnitude` Float64, `direction` String, `disparity` Float64, `windows_evaluated` UInt64, `windows_agree` UInt64, `center_before_w20` Float64, `center_after_w20` Float64, `center_before_w50` Float64, `center_after_w50` Float64, `center_before_w100` Float64, `center_after_w100` Float64, `refreshed_at` DateTime) AS SELECT test, query_index, metric, leading_sha, any(cp_time) AS cp_time, any(magnitude) AS magnitude, any(direction) AS direction, any(disparity) AS disparity, sum(toUInt32(evaluated)) AS windows_evaluated, sum(toUInt32(agree)) AS windows_agree, anyIf(center_before, window_size = 20) AS center_before_w20, anyIf(center_after, window_size = 20) AS center_after_w20, anyIf(center_before, window_size = 50) AS center_before_w50, anyIf(center_after, window_size = 50) AS center_after_w50, anyIf(center_before, window_size = 100) AS center_before_w100, anyIf(center_after, window_size = 100) AS center_after_w100, max(refreshed_at) AS refreshed_at FROM default.perf_change_points_trust FINAL GROUP BY test, query_index, metric, leading_sha;

CREATE VIEW default.perf_change_points_trust_rollup_v2 (`arch` String, `test` String, `query_index` UInt32, `metric` String, `leading_sha` String, `cp_time` DateTime, `magnitude` Float64, `direction` String, `disparity` Float64, `windows_evaluated` UInt64, `windows_agree` UInt64, `center_before_w20` Float64, `center_after_w20` Float64, `center_before_w50` Float64, `center_after_w50` Float64, `center_before_w100` Float64, `center_after_w100` Float64, `refreshed_at` DateTime) AS SELECT arch, test, query_index, metric, leading_sha, any(cp_time) AS cp_time, any(magnitude) AS magnitude, any(direction) AS direction, any(disparity) AS disparity, sum(toUInt32(evaluated)) AS windows_evaluated, sum(toUInt32(agree)) AS windows_agree, anyIf(center_before, window_size = 20) AS center_before_w20, anyIf(center_after, window_size = 20) AS center_after_w20, anyIf(center_before, window_size = 50) AS center_before_w50, anyIf(center_after, window_size = 50) AS center_after_w50, anyIf(center_before, window_size = 100) AS center_before_w100, anyIf(center_after, window_size = 100) AS center_after_w100, max(refreshed_at) AS refreshed_at FROM default.perf_change_points_trust_v2 FINAL GROUP BY arch, test, query_index, metric, leading_sha;
